action actionWithLoop2 {
  in attribute x:Integer;
  out attribute y:Integer;
  attribute increment:Integer = 1;
  first start;
  then assign y := 0;
  then action loop2
  while x < 10 {
    assign y := 2*x;
    then assign x := x + increment;
  }
  then done;
}

action actionWithLoop3 {
  in attribute n:Integer;
  out attribute y:Integer;
  first start;
  then assign y := 0;
  then action forLoop1
  for i : Integer in 1..n {
    assign y := y + i;
  }
  then done;
}

